-- S44 音色词表:豆包 TTS 音色是供应商侧固定标识,落词表,不做远程拉取
-- (R9 创作词汇词表化;机制照 031 的自指 canonical:别名与规范词同表,规范词指向自己,
-- 读取层一跳解析,不做多级链)。"御姐音""甜妹音"这类叫法以后作为别名行登记,
-- voice_type 留空、canonical_id 指向规范词;本迁移只播规范词,不播别名。
--
-- 种子出处(裁决 2:只来自官方文档,一个都不许编):
--   火山引擎官方文档《音色列表》(豆包语音 Doubao Voice 文档库 6561,DocumentID 1257544,
--   页面更新时间 2026-07-20):https://www.volcengine.com/docs/6561/1257544
--   收录该页三张音色表的 586 个 voice_type:
--     「豆包语音合成模型2.0 音色列表」292 条(含 ICL_uranus_* 复刻音色),
--     「豆包语音合成模型2.0 多语种音色列表」151 条,
--     「豆包语音合成模型1.0 音色列表」143 条。
--   文档中 6 个 voice_type 以不同名称重复出现(如 zh_female_sophie_conversation_wvae_bigtts
--   同时作「魅力苏菲」与「Sophie」),取首见行。文档另有「端到端实时语音大模型
--   S2S-O/SC-2.0 音色表」(saturn_*/jupiter_*),那是实时 S2S 接口的音色,不是语音合成
--   TTS 的 voice_type,不收录——收进来会在合成/试听时运行期才失败。
--   分类取「场景」列首个取值;语种取「语种/方言」列首个取值;性别由 voice_type 中
--   female/male 片段机械导出;支持能力/特殊标签等编辑性字段不落库。
--
-- audition_url 一律置空:试听是预渲染产物(固定试听词 -> 每音色渲染一次 -> TOS 静态 URL),
-- 由 scripts/render-voice-auditions.mts 经显式授权后批量写回;本迁移不发任何供应商请求。
--
-- 前向迁移:由 `npm run db:migrate` 显式执行;应用启动不自动执行迁移。
-- 全部语句幂等,可安全重放(CREATE IF NOT EXISTS / ON CONFLICT DO NOTHING)。
--
-- 回滚口径(先备份;旧代码不读取本表,也可直接保留):
--   DROP TABLE IF EXISTS {{schema}}.voice_vocabulary;

CREATE TABLE IF NOT EXISTS {{schema}}.voice_vocabulary (
  id varchar(96) PRIMARY KEY,
  canonical_id varchar(96) NOT NULL REFERENCES {{schema}}.voice_vocabulary(id),
  -- 规范词行:供应商 voice_type(与 id 同值);别名行:NULL。
  voice_type varchar(96),
  display_name varchar(128) NOT NULL,
  language varchar(64),
  category varchar(64),
  gender varchar(16),
  -- 试听预渲染产物的静态 URL;未渲染的音色为 NULL,前端据此置灰试听按钮。
  audition_url text,
  sort int NOT NULL DEFAULT 0,
  active boolean NOT NULL DEFAULT true,
  created_by uuid REFERENCES {{schema}}.users(id),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS voice_vocabulary_canonical_idx
  ON {{schema}}.voice_vocabulary (canonical_id);


-- 种子 1/3:「豆包语音合成模型2.0」音色列表(同上出处)
ON CONFLICT (id) DO NOTHING;

-- 种子 2/3:「豆包语音合成模型2.0」多语种音色列表(同上出处)
ON CONFLICT (id) DO NOTHING;

-- 种子 3/3:「豆包语音合成模型1.0」音色列表(同上出处)
ON CONFLICT (id) DO NOTHING;
